var path="Assets/Scenes/CM_CrookedMortar_ConceptReconstruction02.unity";
if(System.IO.File.Exists(path))throw new System.Exception("Redesign scene already exists; refusing overwrite");
if(UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode)throw new System.Exception("Require Edit mode");
var previous=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(previous.isDirty)throw new System.Exception("Current scene is dirty; preserving it");
var dir="Assets/BlightBloom/Art/Architecture/CrookedMortar/ConceptReconstruction02";
UnityEditor.AssetDatabase.ImportAsset(dir+"/Models/CM_ConceptReconstruction02.fbx",UnityEditor.ImportAssetOptions.ForceSynchronousImport);
System.IO.Directory.CreateDirectory(dir+"/Materials");UnityEditor.AssetDatabase.Refresh();
var materials=new System.Collections.Generic.Dictionary<string,UnityEngine.Material>();
foreach(var key in new[]{"Plaster","Timber","Slate","Stone","Glass"}){var m=new UnityEngine.Material(UnityEngine.Shader.Find("Universal Render Pipeline/Lit"));m.name="CM_Concept02_"+key;float v=key=="Plaster"?.62f:key=="Timber"?.29f:key=="Slate"?.35f:key=="Stone"?.48f:.12f;m.SetColor("_BaseColor",new UnityEngine.Color(v,v,v));m.SetFloat("_Smoothness",0);m.SetFloat("_Metallic",0);m.SetFloat("_SpecularHighlights",0);m.SetFloat("_EnvironmentReflections",0);UnityEditor.AssetDatabase.CreateAsset(m,dir+"/Materials/"+m.name+".mat");materials[key]=m;}
UnityEngine.Material Flat(string name,UnityEngine.Color col){var m=new UnityEngine.Material(UnityEngine.Shader.Find("Universal Render Pipeline/Lit"));m.name=name;m.SetColor("_BaseColor",col);m.SetFloat("_Smoothness",0);UnityEditor.AssetDatabase.CreateAsset(m,dir+"/Materials/"+name+".mat");return m;}
var groundMat=Flat("CM_Concept02_Site",new UnityEngine.Color(.38f,.38f,.38f));var proxyMat=Flat("CM_Concept02_ProxyWood",new UnityEngine.Color(.29f,.29f,.29f));var pathMat=Flat("CM_Concept02_Path",new UnityEngine.Color(.48f,.48f,.48f));
var scene=UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Additive);UnityEngine.SceneManagement.SceneManager.SetActiveScene(scene);
UnityEngine.Transform Group(string name,UnityEngine.Transform parent=null){var g=new UnityEngine.GameObject(name);if(parent!=null)g.transform.SetParent(parent,false);return g.transform;}
UnityEngine.GameObject Box(string name,UnityEngine.Transform parent,UnityEngine.Vector3 pos,UnityEngine.Vector3 size,UnityEngine.Material mat){var g=UnityEngine.GameObject.CreatePrimitive(UnityEngine.PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.position=pos;g.transform.localScale=size;g.GetComponent<UnityEngine.Renderer>().sharedMaterial=mat;return g;}
var architecture=Group("01 Authored architecture - offset volumes");var source=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(dir+"/Models/CM_ConceptReconstruction02.fbx");var body=(UnityEngine.GameObject)UnityEditor.PrefabUtility.InstantiatePrefab(source,scene);body.name="CM_Concept02_Architecture";body.transform.SetParent(architecture,false);
foreach(var r in body.GetComponentsInChildren<UnityEngine.Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>materials[materials.Keys.First(k=>m.name.Contains(k))]).ToArray();
foreach(var mf in body.GetComponentsInChildren<UnityEngine.MeshFilter>()){var c=mf.gameObject.AddComponent<UnityEngine.MeshCollider>();c.sharedMesh=mf.sharedMesh;}
var modules=Group("02 Approved facade modules");
UnityEngine.GameObject Module(string prefab,string name,UnityEngine.Vector3 pos,UnityEngine.Vector3 scale){var asset=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(prefab);if(asset==null)throw new System.Exception("Approved asset missing "+prefab);var g=(UnityEngine.GameObject)UnityEditor.PrefabUtility.InstantiatePrefab(asset,scene);g.name=name;g.transform.SetParent(modules,false);g.transform.position=pos;g.transform.rotation=UnityEngine.Quaternion.Euler(0,180,0);g.transform.localScale=scale;return g;}
var entrance=Module("Assets/BlightBloom/Art/Architecture/CrookedMortar/EntranceBay01/Prefabs/CM_EntranceBay01_Painted_v01.prefab","Recessed entrance - approved door only",new UnityEngine.Vector3(.8f,0,-3.035f),new UnityEngine.Vector3(.78f,1,1));
foreach(var t in entrance.GetComponentsInChildren<UnityEngine.Transform>()){
if(t.name.StartsWith("01_")||t.name.StartsWith("04_")||t.name.StartsWith("06_")||t.name.StartsWith("07_")||t.name.StartsWith("08_"))t.gameObject.SetActive(false);
