}
var windowPrefab="Assets/BlightBloom/Art/Architecture/CrookedMortar/WindowBay01/Prefabs/CM_WindowBay01_Painted_v02.prefab";
var hero=Module(windowPrefab,"A Main front gable window",new UnityEngine.Vector3(-.25f,3.25f,-3.335f),UnityEngine.Vector3.one);
var wing=Module(windowPrefab,"C Lower parallel gable window",new UnityEngine.Vector3(4.4f,3.65f,1.765f),UnityEngine.Vector3.one*.8f);
var sideWindow=Module(windowPrefab,"A Side window over low shop",new UnityEngine.Vector3(2.835f,3.475f,.25f),new UnityEngine.Vector3(.875f,.9f,.9f));sideWindow.transform.rotation=UnityEngine.Quaternion.Euler(0,90,0);
foreach(var g in new[]{hero,wing,sideWindow})foreach(var t in g.GetComponentsInChildren<UnityEngine.Transform>())if(t.name.StartsWith("01_")||t.name.StartsWith("04_")||t.name.StartsWith("05_")||t.name.StartsWith("06_")||t.name.StartsWith("07_"))t.gameObject.SetActive(false);
foreach(var r in modules.GetComponentsInChildren<UnityEngine.Renderer>(true))r.sharedMaterials=r.sharedMaterials.Select(m=>materials[m.name.Contains("Glass")?"Glass":m.name.Contains("Plaster")?"Plaster":m.name.Contains("Stone")?"Stone":m.name.Contains("Slate")?"Slate":"Timber"]).ToArray();
var site=Group("03 Plain site - no decoration");Box("Village ground",site,new UnityEngine.Vector3(1,-.15f,1),new UnityEngine.Vector3(36,.3f,36),groundMat);
var rooms=Group("04 Functional room plan");
foreach(var name in new[]{"Ground - front public shop and side dispensing bay","Ground - rear right treatment room","Ground - right wing medicine preparation","Ground - rear storage and garden exit","Upper - front left bedroom","Upper - front right living quarters","Upper - rear right reading nook","Upper - lower parallel wing medical library and study","U stair - 18 risers, two flights and generous turning landing"})Group(name,rooms);
