var traversal=Group("05 Existing traversal setup");var spawn=Group("Front approach spawn",traversal);spawn.position=new UnityEngine.Vector3(.8f,.05f,-7.5f);
var player=new UnityEngine.GameObject("Redesign Prototype Player");player.transform.SetParent(traversal,false);player.transform.position=spawn.position;
