var actions=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.InputSystem.InputActionAsset>("Assets/InputSystem_Actions.inputactions");var input=player.AddComponent<BlightBloom.Traversal.TraversalInput>();input.Configure(actions);var motor=player.AddComponent<BlightBloom.Traversal.ThirdPersonMotor>();
var visual=UnityEngine.GameObject.CreatePrimitive(UnityEngine.PrimitiveType.Capsule);visual.name="Player capsule visual";visual.transform.SetParent(player.transform,false);visual.transform.localPosition=UnityEngine.Vector3.up;UnityEngine.Object.DestroyImmediate(visual.GetComponent<UnityEngine.Collider>());visual.GetComponent<UnityEngine.Renderer>().sharedMaterial=proxyMat;
var cameraGo=new UnityEngine.GameObject("Redesign Traversal Camera");cameraGo.transform.SetParent(traversal,false);cameraGo.tag="MainCamera";var cam=cameraGo.AddComponent<UnityEngine.Camera>();cam.fieldOfView=65;cam.nearClipPlane=.05f;cam.farClipPlane=150;cameraGo.AddComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();cameraGo.AddComponent<UnityEngine.AudioListener>();var orbit=cameraGo.AddComponent<BlightBloom.Traversal.ThirdPersonOrbitCamera>();orbit.Configure(player.transform,input);orbit.ConfigureObstruction(true,3);motor.Configure(input,cameraGo.transform);cameraGo.transform.SetPositionAndRotation(spawn.position+new UnityEngine.Vector3(0,2.5f,-3),UnityEngine.Quaternion.Euler(20,0,0));
var lightGo=new UnityEngine.GameObject("Soft daylight");var light=lightGo.AddComponent<UnityEngine.Light>();light.type=UnityEngine.LightType.Directional;light.intensity=1.5f;light.shadows=UnityEngine.LightShadows.Soft;lightGo.transform.rotation=UnityEngine.Quaternion.Euler(38,-35,0);UnityEngine.RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;UnityEngine.RenderSettings.ambientSkyColor=new UnityEngine.Color(.61f,.64f,.68f);UnityEngine.RenderSettings.ambientEquatorColor=new UnityEngine.Color(.48f,.49f,.51f);UnityEngine.RenderSettings.ambientGroundColor=new UnityEngine.Color(.28f,.27f,.25f);
var views=Group("06 Neutral silhouette review cameras");var names=new[]{"Front","ThreeQuarter","Side"};var positions=new[]{new UnityEngine.Vector3(1,5.5f,-26),new UnityEngine.Vector3(20,7,-24),new UnityEngine.Vector3(29,6,1.5f)};
for(int i=0;i<3;i++){var g=new UnityEngine.GameObject("Concept02Review_"+names[i]);g.transform.SetParent(views,false);var c=g.AddComponent<UnityEngine.Camera>();c.enabled=false;c.clearFlags=UnityEngine.CameraClearFlags.SolidColor;c.backgroundColor=new UnityEngine.Color(.3f,.32f,.34f);c.fieldOfView=32;c.nearClipPlane=.1f;c.farClipPlane=200;g.transform.position=positions[i];g.transform.LookAt(new UnityEngine.Vector3(1,5.5f,1));}
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,path);UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.CloseScene(previous,true);UnityEditor.Selection.activeGameObject=body;
return "Created isolated redesign scene; source parts="+body.GetComponentsInChildren<UnityEngine.MeshFilter>().Length+"; previous scene preserved; input/motor/orbit code reused unchanged.";
